import { useEffect, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useToast } from "@/hooks/use-toast";
import {
  Bookmark, BookmarkX, ExternalLink, Search, RefreshCw,
  AlertTriangle, Trash2, Clock, Tag, X,
} from "lucide-react";
import { type WatchedItem, loadWatchlist, useWatchlist } from "@/lib/watchlist";

export { useWatchlist };

const SEV_BADGE: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/40",
  high:     "bg-orange-400/15 text-orange-400 border-orange-400/40",
  medium:   "bg-blue-400/15 text-blue-400 border-blue-400/40",
  low:      "bg-green-500/15 text-green-400 border-green-500/40",
};

const SEV_BORDER: Record<string, string> = {
  critical: "border-l-red-500",
  high:     "border-l-orange-400",
  medium:   "border-l-blue-400",
  low:      "border-l-green-500",
};

function timeAgo(iso: string) {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

export default function Watchlist() {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [search, setSearch] = useState("");
  const [sevFilter, setSevFilter] = useState("all");
  const [editingNote, setEditingNote] = useState<string | null>(null);
  const [noteText, setNoteText] = useState("");
  const [refreshing, setRefreshing] = useState(false);
  const [liveData, setLiveData] = useState<Record<string, Partial<WatchedItem>>>({});

  // TanStack Query for watchlist
  const { data: items = [], refetch } = useQuery({
    queryKey: ["watchlist"],
    queryFn: loadWatchlist,
    staleTime: 60_000,
  });

  // Refresh live data for all watched items from Supabase
  const refreshLive = async () => {
    if (items.length === 0) return;
    setRefreshing(true);
    const ids = items.map(i => i.id);
    const { data } = await supabase
      .from("threat_items")
      .select("id,title,severity,ai_summary,published_at")
      .in("id", ids);
    if (data) {
      const map: Record<string, Partial<WatchedItem>> = {};
      data.forEach((d: any) => { map[d.id] = d; });
      setLiveData(map);
    }
    setRefreshing(false);
  };

  useEffect(() => { refreshLive(); }, [items.length]);

  const removeItem = async (id: string) => {
    await supabase.from("saved_threats").delete().eq("id", id);
    queryClient.setQueryData<WatchedItem[]>(["watchlist"], old => old?.filter(i => i.id !== id) ?? []);
    toast({ title: "Removed from watchlist" });
  };

  const saveNote = async (id: string) => {
    await supabase.from("saved_threats").update({ notes: noteText }).eq("id", id);
    queryClient.setQueryData<WatchedItem[]>(["watchlist"], old => old?.map(i => i.id === id ? { ...i, notes: noteText } : i) ?? []);
    setEditingNote(null);
    toast({ title: "Note saved" });
  };

  const clearAll = async () => {
    const ids = items.map(i => i.id);
    if (ids.length > 0) await supabase.from("saved_threats").delete().in("id", ids);
    queryClient.setQueryData(["watchlist"], []);
    toast({ title: "Watchlist cleared" });
  };

  const filtered = items.filter(item => {
    if (sevFilter !== "all" && item.severity !== sevFilter) return false;
    if (search) {
      const s = search.toLowerCase();
      return item.title.toLowerCase().includes(s) ||
        item.source_name.toLowerCase().includes(s) ||
        item.category.toLowerCase().includes(s);
    }
    return true;
  });

  const stats = {
    total: items.length,
    critical: items.filter(i => i.severity === "critical").length,
    high: items.filter(i => i.severity === "high").length,
    withNotes: items.filter(i => i.notes).length,
  };

  return (
    <div className="container mx-auto px-4 py-8 max-w-5xl">
      {/* Header */}
      <div className="mb-8 flex items-start justify-between gap-4">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <Bookmark className="h-6 w-6 text-primary" />
            <h1 className="text-3xl font-bold tracking-tight">Watchlist</h1>
          </div>
          <p className="text-muted-foreground">
            Bookmarked threats you're actively monitoring. Add items from the Live Feed or Dashboard.
          </p>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <Button
            size="sm" variant="outline"
            onClick={refreshLive}
            disabled={refreshing}
            className="gap-1.5 h-8 text-xs"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
          {items.length > 0 && (
            <Button
              size="sm" variant="outline"
              onClick={clearAll}
              className="gap-1.5 h-8 text-xs text-destructive hover:text-destructive"
            >
              <Trash2 className="h-3.5 w-3.5" /> Clear All
            </Button>
          )}
        </div>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-4 gap-3 mb-6">
        {[
          { label: "Watching", value: stats.total, color: "text-foreground" },
          { label: "Critical", value: stats.critical, color: "text-destructive" },
          { label: "High", value: stats.high, color: "text-orange-400" },
          { label: "With Notes", value: stats.withNotes, color: "text-primary" },
        ].map(s => (
          <Card key={s.label} className="border-border/60">
            <CardContent className="px-4 py-3 text-center">
              <div className={`text-2xl font-bold tabular-nums ${s.color}`}>{s.value}</div>
              <div className="text-xs text-muted-foreground mt-0.5">{s.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Filters */}
      <div className="flex items-center gap-2 mb-5">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search watchlist…"
            className="h-8 pl-8 text-xs"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-2 top-1/2 -translate-y-1/2">
              <X className="h-3 w-3 text-muted-foreground" />
            </button>
          )}
        </div>
        <div className="flex items-center gap-1">
          {["all", "critical", "high", "medium", "low"].map(s => (
            <button
              key={s}
              onClick={() => setSevFilter(s)}
              className={`h-8 px-3 rounded-md text-xs font-medium transition-colors border ${
                sevFilter === s
                  ? "bg-primary/15 text-primary border-primary/40"
                  : "text-muted-foreground border-border/60 hover:bg-muted/60"
              }`}
            >
              {s.charAt(0).toUpperCase() + s.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Empty state */}
      {items.length === 0 && (
        <Card className="border-dashed border-border/60">
          <CardContent className="py-16 text-center">
            <Bookmark className="h-10 w-10 text-muted-foreground/30 mx-auto mb-4" />
            <h3 className="text-base font-semibold mb-2">No items in your watchlist</h3>
            <p className="text-sm text-muted-foreground max-w-xs mx-auto">
              Click the bookmark icon on any threat card in the Live Feed or Dashboard to start tracking it here.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Items */}
      {filtered.length === 0 && items.length > 0 && (
        <div className="text-center py-12 text-sm text-muted-foreground">
          No items match the current filter.
        </div>
      )}

      <div className="flex flex-col gap-3">
        {filtered.map(item => {
          const live = liveData[item.id];
          const currentSeverity = (live?.severity as string) || item.severity;
          const sevChanged = live?.severity && live.severity !== item.severity;

          return (
            <Card
              key={item.id}
              className={`border-l-4 border-border/60 transition-colors ${SEV_BORDER[currentSeverity] || "border-l-border"}`}
            >
              <CardContent className="px-5 py-4">
                <div className="flex items-start gap-3">
                  <div className="flex-1 min-w-0">
                    {/* Title row */}
                    <div className="flex items-start gap-2 mb-2">
                      <span className={`shrink-0 text-[9px] font-bold px-1.5 py-0.5 rounded border ${SEV_BADGE[currentSeverity] || ""}`}>
                        {currentSeverity.toUpperCase()}
                        {sevChanged && <span className="ml-1 text-yellow-400">↑</span>}
                      </span>
                      <p className="text-sm font-medium leading-snug">{item.title}</p>
                    </div>

                    {/* Meta */}
                    <div className="flex items-center gap-3 text-[11px] text-muted-foreground mb-2 flex-wrap">
                      <span>{item.source_name}</span>
                      <span className="text-border">·</span>
                      <span>{item.category}</span>
                      <span className="text-border">·</span>
                      <span className="flex items-center gap-1">
                        <Clock className="h-2.5 w-2.5" />
                        Published {timeAgo(item.published_at)}
                      </span>
                      <span className="flex items-center gap-1">
                        <Bookmark className="h-2.5 w-2.5 text-primary" />
                        Saved {timeAgo(item.saved_at)}
                      </span>
                    </div>

                    {/* AI summary if available */}
                    {(live?.ai_summary || item.ai_summary) && (
                      <p className="text-xs text-muted-foreground line-clamp-2 mb-2 pl-2 border-l-2 border-primary/30">
                        {(live?.ai_summary || item.ai_summary || "").slice(0, 200)}…
                      </p>
                    )}

                    {/* Note */}
                    {editingNote === item.id ? (
                      <div className="flex items-center gap-2 mt-2">
                        <Input
                          value={noteText}
                          onChange={e => setNoteText(e.target.value)}
                          placeholder="Add a note about this threat…"
                          className="h-7 text-xs flex-1"
                          autoFocus
                          onKeyDown={e => { if (e.key === "Enter") saveNote(item.id); if (e.key === "Escape") setEditingNote(null); }}
                        />
                        <Button size="sm" className="h-7 text-xs px-3" onClick={() => saveNote(item.id)}>Save</Button>
                        <Button size="sm" variant="ghost" className="h-7 text-xs px-2" onClick={() => setEditingNote(null)}>Cancel</Button>
                      </div>
                    ) : item.notes ? (
                      <div
                        className="flex items-start gap-1.5 text-xs text-muted-foreground mt-2 cursor-pointer hover:text-foreground"
                        onClick={() => { setEditingNote(item.id); setNoteText(item.notes || ""); }}
                      >
                        <Tag className="h-3 w-3 mt-0.5 text-primary shrink-0" />
                        <span>{item.notes}</span>
                      </div>
                    ) : null}
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1 shrink-0">
                    {item.link && (
                      <Button size="sm" variant="ghost" className="h-7 w-7 p-0" asChild>
                        <a href={item.link} target="_blank" rel="noreferrer">
                          <ExternalLink className="h-3.5 w-3.5" />
                        </a>
                      </Button>
                    )}
                    <Button
                      size="sm" variant="ghost"
                      className="h-7 px-2 text-xs gap-1 text-muted-foreground hover:text-foreground"
                      onClick={() => { setEditingNote(item.id); setNoteText(item.notes || ""); }}
                    >
                      <Tag className="h-3 w-3" />
                      {item.notes ? "Edit note" : "Add note"}
                    </Button>
                    <Button
                      size="sm" variant="ghost"
                      className="h-7 w-7 p-0 text-muted-foreground hover:text-destructive"
                      onClick={() => removeItem(item.id)}
                    >
                      <BookmarkX className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
